from pydantic import BaseModel


class SimulationState(BaseModel):
    running: bool
    tick: int
    scenario_phase: str
    elapsed: float


class SimulationStartRequest(BaseModel):
    speed_ms: int | None = None


class SimulationPauseRequest(BaseModel):
    pass


class SimulationResetRequest(BaseModel):
    pass

from fastapi import APIRouter
from fastapi.websockets import WebSocket

from backend.services.simulation import engine, manager
from backend.schemas.simulation import (
    SimulationState,
    SimulationStartRequest,
    SimulationPauseRequest,
    SimulationResetRequest,
)

router = APIRouter(prefix="/api/simulation", tags=["simulation"])


@router.get("/status", response_model=SimulationState)
def simulation_status() -> SimulationState:
    state = engine.get_state()
    return SimulationState(**state)


@router.post("/start")
async def simulation_start(req: SimulationStartRequest) -> dict[str, str]:
    await engine.start(req.speed_ms)
    return {"status": "started", "tick": engine.tick}


@router.post("/pause")
async def simulation_pause(req: SimulationPauseRequest) -> dict[str, str]:
    await engine.pause()
    return {"status": "paused", "tick": engine.tick}


@router.post("/reset")
async def simulation_reset(req: SimulationResetRequest) -> dict[str, str]:
    await engine.reset()
    return {"status": "reset", "tick": 0}


@router.websocket("/ws/live")
async def websocket_live(websocket: WebSocket) -> None:
    await manager.connect(websocket)
    try:
        while True:
            await websocket.receive_text()
    except Exception:
        pass
    finally:
        manager.disconnect(websocket)

