  status: string;
  risk_score: number;
  priority: number;
  confidence: number;
  information_void_score: number;
  last_verified: string | null;
  report_count: number;
  created_at: string;
  updated_at: string;
}

export interface Incident {
  id: string;
  title: string;
  event_type: string;
  latitude: number;
  longitude: number;
  area_id: string | null;
  severity: string;
  people_affected: number;
  people_trapped: number;
  vulnerable_population: number;
  confidence: number;
  priority: number;
  status: string;
  created_at: string;
  updated_at: string;
}

export interface Resource {
  id: string;
  type: string;
  status: string;
  latitude: number;
  longitude: number;
  capacity: number;
  availability: number;
  created_at: string;
