}

export interface Report {
  id: string;
  timestamp: string;
  source_type: string;
  source_name: string;
  latitude: number;
  longitude: number;
  location_name: string;
  raw_text: string;
  media_type: string;
  claimed_severity: number;
  people_affected: number;
  people_trapped: number;
  vulnerable_population: number;
  event_type: string;
  evidence_type: string;
  confidence: number;
  status: string;
  incident_id: string | null;
  created_at: string;
}

export interface SimulationState {
  running: boolean;
  tick: number;
  scenario_phase: string;
  elapsed: number;
}

export interface SimulationStartRequest {
  speed_ms?: number;
}

const BASE = import.meta.env.VITE_API_URL ?? 'http://localhost:8000/api';

async function request<T>(path: string, options?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options?.headers ?? {}) },
    ...options,
  });
  if (!res.ok) {
    throw new Error(`API ${res.status}: ${res.statusText}`);
  }
  return res.json() as Promise<T>;
}

export const api = {
  health: () => request<{ status: string; database: string; simulation_running: boolean }>('/health'),
  areas: (params?: { status?: string; min_priority?: number }) => {
    const qs = new URLSearchParams();
    if (params?.status) qs.set('status', params.status);
    if (params?.min_priority !== undefined) qs.set('min_priority', String(params.min_priority));
    return request<Area[]>(`/areas${qs.toString() ? `?${qs}` : ''}`);
  },
  incidents: (params?: { severity?: string; status?: string; area_id?: string }) => {
    const qs = new URLSearchParams();
    if (params?.severity) qs.set('severity', params.severity);
    if (params?.status) qs.set('status', params.status);
    if (params?.area_id) qs.set('area_id', params.area_id);
    return request<Incident[]>(`/incidents${qs.toString() ? `?${qs}` : ''}`);
  },
  resources: () => request<Resource[]>('/resources'),
  reports: (params?: { source_type?: string; status?: string; incident_id?: string }) => {
    const qs = new URLSearchParams();
    if (params?.source_type) qs.set('source_type', params.source_type);
    if (params?.status) qs.set('status', params.status);
    if (params?.incident_id) qs.set('incident_id', params.incident_id);
    return request<Report[]>(`/reports${qs.toString() ? `?${qs}` : ''}`);
  },
  simulationStatus: () => request<SimulationState>('/simulation/status'),
  simulationStart: (speedMs?: number) =>
    request<{ status: string; tick: number }>('/simulation/start', {
      method: 'POST',
      body: JSON.stringify({ speed_ms: speedMs } satisfies SimulationStartRequest),
    }),
  simulationPause: () =>
    request<{ status: string; tick: number }>('/simulation/pause', { method: 'POST', body: '{}' }),
  simulationReset: () =>
    request<{ status: string; tick: number }>('/simulation/reset', { method: 'POST', body: '{}' }),
};

import { useEffect, useMemo, useState } from 'react';
import { api, type Area, type Incident, type Resource, type Report, type SimulationState } from '../api';

export function useAreas() {
  const [items, setItems] = useState<Area[]>([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    let cancelled = false;
    api.areas().then((data) => {
      if (!cancelled) {
        setItems(data);
        setLoading(false);
      }
    });
    return () => { cancelled = true; };
  }, []);
  return { items, loading };
}

export function useIncidents() {
  const [items, setItems] = useState<Incident[]>([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    let cancelled = false;
    api.incidents().then((data) => {
      if (!cancelled) {
        setItems(data);
        setLoading(false);
      }
    });
    return () => { cancelled = true; };
  }, []);
  return { items, loading };
}

export function useResources() {
  const [items, setItems] = useState<Resource[]>([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    let cancelled = false;
    api.resources().then((data) => {
      if (!cancelled) {
        setItems(data);
        setLoading(false);
      }
    });
    return () => { cancelled = true; };
  }, []);
  return { items, loading };
}

export function useReports() {
  const [items, setItems] = useState<Report[]>([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    let cancelled = false;
    api.reports().then((data) => {
      if (!cancelled) {
        setItems(data);
        setLoading(false);
      }
    });
    return () => { cancelled = true; };
  }, []);
  return { items, loading };
}

export function useSimulation() {
  const [state, setState] = useState<SimulationState | null>(null);
  const [tick, setTick] = useState(0);

  useEffect(() => {
    let ws: WebSocket | null = null;
    const connect = () => {
      const proto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
      ws = new WebSocket(`${proto}//${window.location.host}/api/simulation/ws/live`);
      ws.onmessage = (ev) => {
        try {
          const msg = JSON.parse(ev.data);
          if (msg?.event === 'SIMULATION_TICK') {
            setTick((msg.payload.tick as number) ?? 0);
          }
        } catch {
          // ignore parse errors
        }
      };
      ws.onclose = () => setTimeout(connect, 2000);
    };
    connect();
    return () => { ws?.close(); };
  }, []);

  useEffect(() => {
    let cancelled = false;
    api.simulationStatus().then((s) => { if (!cancelled) setState(s); });
    return () => { cancelled = true; };
  }, [tick]);

  const start = async (speedMs?: number) => {
    await api.simulationStart(speedMs);
  };
  const pause = async () => { await api.simulationPause(); };
  const reset = async () => { await api.simulationReset(); };

  return { state: state ?? { running: false, tick: 0, scenario_phase: 'normal', elapsed: 0 }, start, pause, reset };
}

export function severityColor(severity: string): string {
  const map: Record<string, string> = {
    low: '#4ade80',
    moderate: '#facc15',
    high: '#fb923c',
    severe: '#f87171',
    critical: '#ef4444',
  };
  return map[severity] ?? '#9ca3af';
}

export function statusColor(status: string): string {
  const map: Record<string, string> = {
    normal: '#4ade80',
    at_risk: '#facc15',
    affected: '#fb923c',
    severe: '#f87171',
    information_void: '#94a3b8',
    active: '#ef4444',
    contained: '#facc15',
    resolved: '#4ade80',
    monitoring: '#60a5fa',
    available: '#4ade80',
    deployed: '#60a5fa',
    unavailable: '#94a3b8',
    maintenance: '#facc15',
    pending: '#facc15',
    verified: '#4ade80',
    disputed: '#f87171',
    merged: '#94a3b8',
  };
  return map[status] ?? '#9ca3af';
}

export function useFilteredAreas(items: Area[]) {
  return useMemo(() => {
    const byStatus = new Map<string, Area[]>();
    for (const a of items) {
      const arr = byStatus.get(a.status) ?? [];
      arr.push(a);
      byStatus.set(a.status, arr);
    }
    return byStatus;
  }, [items]);
}

import { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { type PmtilesAdapter } from 'pmtiles';
import { type Area, type Incident, type Resource, severityColor, statusColor } from '../hooks';

const ADAPTER = new (await import('pmtiles')).PmtilesAdapter();

function createPmtilesSource(map: maplibregl.Map, id: string, url: string) {
  const source: maplibregl.GeoJSONSource = {
    type: 'geojson',
    data: { type: 'FeatureCollection', features: [] },
  };
  (map as any).addSource(id, source);
  ADAPTER.getVectorTiles(url).then((tileSource) => {
    (map as any).addSource(`${id}-pmtiles`, {
      type: 'vector',
      tiles: [tileSource.getTileUrl({ x: 0, y: 0, z: 0 })],
      minzoom: tileSource.minZoom,
      maxzoom: tileSource.maxZoom,
    });
  });
}

export function MapView({
  areas,
  incidents,
  resources,
}: {
  areas: Area[];
  incidents: Incident[];
  resources: Resource[];
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;

    const map = new maplibregl.Map({
      container: containerRef.current,
      style: {
        version: 8,
        sources: {
          'osm-tiles': {
            type: 'raster',
            tiles: ['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],
            tileSize: 256,
            attribution: '© OpenStreetMap contributors',
            maxzoom: 19,
          },
        },
        layers: [
          {
            id: 'osm-tiles-layer',
            type: 'raster',
            source: 'osm-tiles',
          },
        ],
      },
      center: [91.7362, 26.1445],
      zoom: 12,
      hash: true,
    });

    map.addControl(new maplibregl.NavigationControl(), 'top-right');
    map.addControl(new maplibregl.ScaleControl({ maxWidth: 120 }), 'bottom-left');

    map.on('load', () => {
      // Try to add local PMTiles as an alternative base layer
      const pmtilesUrl = '/data/guwahati/wards_guwahati.pmtiles';
      try {
        const source: maplibregl.VectorSource = {
          type: 'vector',
          tiles: [`pmtiles://${pmtilesUrl}`],
          maxzoom: 14,
        };
        (map as any).addSource('guwahati-pmtiles', source);
        (map as any).addLayer({
          id: 'wards-fill',
          type: 'fill',
          source: 'guwahati-pmtiles',
          'source-layer': 'wards_guwahati',
          paint: {
            'fill-color': '#1e293b',
            'fill-opacity': 0.3,
          },
        });
        (map as any).addLayer({
          id: 'wards-line',
          type: 'line',
          source: 'guwahati-pmtiles',
          'source-layer': 'wards_guwahati',
          paint: {
            'line-color': '#334155',
            'line-width': 1,
          },
        });
      } catch {
        // PMTiles not available, fallback to OSM raster
      }

      // Add GeoJSON overlays
      (map as any).addSource('areas', {
        type: 'geojson',
        data: { type: 'FeatureCollection', features: [] },
      });
      (map as any).addSource('incidents', {
        type: 'geojson',
        data: { type: 'FeatureCollection', features: [] },
      });
      (map as any).addSource('resources', {
        type: 'geojson',
        data: { type: 'FeatureCollection', features: [] },
      });

      (map as any).addLayer({
        id: 'incidents-circles',
        type: 'circle',
        source: 'incidents',
        paint: {
          'circle-radius': 8,
          'circle-color': ['get', 'color'],
          'circle-stroke-width': 2,
          'circle-stroke-color': '#0f172a',
        },
      });

      (map as any).addLayer({
        id: 'resources-symbol',
        type: 'symbol',
        source: 'resources',
        layout: {
          'text-field': ['get', 'symbol'],
          'text-size': 12,
          'text-allow-overlap': true,
        },
        paint: {
          'text-color': '#e2e8f0',
          'text-halo-color': '#0f172a',
          'text-halo-width': 1,
        },
      });
    });

    mapRef.current = map;
    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  // Update incident markers
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !map.isStyleLoaded()) return;
    const source = (map as any).getSource('incidents') as maplibregl.GeoJSONSource | undefined;
    if (!source) return;
    const features = incidents.map((inc) => ({
      type: 'Feature' as const,
      properties: {
        id: inc.id,
        title: inc.title,
        severity: inc.severity,
        color: severityColor(inc.severity),
      },
      geometry: {
        type: 'Point' as const,
        coordinates: [inc.longitude, inc.latitude],
      },
    }));
    source.setData({ type: 'FeatureCollection', features });
  }, [incidents]);

  // Update area markers
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !map.isStyleLoaded()) return;
    const source = (map as any).getSource('areas') as maplibregl.GeoJSONSource | undefined;
    if (!source) return;
    const features = areas.map((area) => ({
      type: 'Feature' as const,
      properties: {
        id: area.id,
        name: area.name,
        status: area.status,
        priority: area.priority,
      },
      geometry: {
        type: 'Point' as const,
        coordinates: [area.longitude, area.latitude],
      },
    }));
    source.setData({ type: 'FeatureCollection', features });
  }, [areas]);

  // Update resource markers
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !map.isStyleLoaded()) return;
    const source = (map as any).getSource('resources') as maplibregl.GeoJSONSource | undefined;
    if (!source) return;
    const symbolMap: Record<string, string> = {
      boat: '🚤',
      ambulance: '🚑',
      helicopter: '🚁',
      rescue_team: '👥',
      excavator: '🚜',
      medical_team: '🏥',
      water_tanker: '🚛',
      supply_vehicle: '🚚',
    };
    const features = resources.map((res) => ({
      type: 'Feature' as const,
      properties: {
        id: res.id,
        type: res.type,
        status: res.status,
        symbol: symbolMap[res.type] ?? '•',
      },
      geometry: {
        type: 'Point' as const,
        coordinates: [res.longitude, res.latitude],
      },
    }));
    source.setData({ type: 'FeatureCollection', features });
  }, [resources]);

  return <div ref={containerRef} className="map-container" />;
}

