export const SimulationPanel: FC<{
  state: SimulationState;
  onStart: () => void;
  onPause: () => void;
  onReset: () => void;
}> = ({ state, onStart, onPause, onReset }) => {
  const phaseColor =
    state.scenario_phase === 'information_void' || state.scenario_phase === 'sector_silent'
      ? '#f87171'
      : state.scenario_phase === 'normal'
        ? '#4ade80'
        : '#facc15';

  return (
    <div className="panel simulation-panel">
      <div className="panel-header">
        <Radio className="icon" size={16} />
        <h3>Simulation</h3>
        <span className="badge" style={{ background: state.running ? '#ef4444' : '#475569' }}>
          {state.running ? 'LIVE' : 'PAUSED'}
        </span>
      </div>
      <div className="panel-body">
        <div className="stat-grid">
          <div className="stat">
            <div className="stat-label">Tick</div>
            <div className="stat-value mono">{state.tick}</div>
          </div>
          <div className="stat">
            <div className="stat-label">Elapsed</div>
            <div className="stat-value mono">{state.elapsed.toFixed(1)}s</div>
          </div>
        </div>
        <div className="phase">
          <span className="phase-dot" style={{ background: phaseColor }} />
          <span className="phase-label" style={{ color: phaseColor }}>
            {state.scenario_phase.replace(/_/g, ' ').toUpperCase()}
          </span>
        </div>
        <div className="button-row">
          <button className="btn btn-primary" onClick={onStart} disabled={state.running}>
            Start
          </button>
          <button className="btn btn-warning" onClick={onPause} disabled={!state.running}>
            Pause
          </button>
          <button className="btn btn-ghost" onClick={onReset}>
