import { useState, useEffect } from 'react';
import { Shield } from 'lucide-react';
import { MapView } from './components';
import { useAreas, useIncidents, useResources, useReports, useSimulation } from './hooks';
import {
  AreaPanel,
  IncidentPanel,
  ReportPanel,
  ResourcePanel,
  SimulationPanel,
} from './panels';

type Tab = 'incidents' | 'areas' | 'resources' | 'reports';

function App() {
  const { items: areas, loading: areasLoading } = useAreas();
  const { items: incidents, loading: incidentsLoading } = useIncidents();
  const { items: resources, loading: resourcesLoading } = useResources();
  const { items: reports, loading: reportsLoading } = useReports();
  const sim = useSimulation();

  const [tab, setTab] = useState<Tab>('incidents');
  const [health, setHealth] = useState<{ ok: boolean; simRunning: boolean } | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch('http://localhost:8000/api/health')
      .then((r) => r.json())
      .then((d) => {
        if (!cancelled) setHealth({ ok: d.status === 'ok', simRunning: d.simulation_running });
      })
      .catch(() => {
        if (!cancelled) setHealth({ ok: false, simRunning: false });
      });
    return () => { cancelled = true; };
  }, []);

  const tabs: { key: Tab; label: string }[] = [
    { key: 'incidents', label: 'Incidents' },
    { key: 'areas', label: 'Areas' },
    { key: 'resources', label: 'Resources' },
    { key: 'reports', label: 'Reports' },
  ];

  const loading = areasLoading || incidentsLoading || resourcesLoading || reportsLoading;

  return (
    <div className="app">
      <header className="topbar">
        <div className="brand">
          <Shield className="brand-icon" size={22} />
          <div>
            <div className="brand-name">PRISM</div>
            <div className="brand-sub">Post-Disaster Reality Intelligence &amp; Situation Mapping</div>
          </div>
        </div>
        <div className="topbar-right">
          <span className={`status-pill ${health?.ok ? 'ok' : 'err'}`}>
            {health?.ok ? 'SYSTEM ONLINE' : 'OFFLINE'}
          </span>
          <span className="status-pill sim">
            SIM {sim.state.running ? 'RUNNING' : 'IDLE'}
          </span>
        </div>
      </header>

      <div className="layout">
        <aside className="sidebar">
          <SimulationPanel
            state={sim.state}
            onStart={() => sim.start(2000)}
            onPause={sim.pause}
            onReset={sim.reset}
          />
          <nav className="tabs">
            {tabs.map((t) => (
              <button
                key={t.key}
                className={`tab ${tab === t.key ? 'active' : ''}`}
                onClick={() => setTab(t.key)}
              >
                {t.label}
              </button>
            ))}
          </nav>
          <div className="panel-stack">
            {tab === 'incidents' && <IncidentPanel incidents={incidents} />}
            {tab === 'areas' && <AreaPanel areas={areas} />}
            {tab === 'resources' && <ResourcePanel resources={resources} />}
            {tab === 'reports' && <ReportPanel reports={reports} />}
          </div>
        </aside>

        <main className="main">
          {loading ? (
            <div className="loading">Loading operational data...</div>
          ) : (
            <MapView areas={areas} incidents={incidents} resources={resources} />
          )}
          <div className="map-overlay-bottom">
            <div className="legend">
              <span className="legend-item"><span className="legend-dot" style={{ background: '#ef4444' }} /> Critical</span>
              <span className="legend-item"><span className="legend-dot" style={{ background: '#facc15' }} /> Moderate</span>
              <span className="legend-item"><span className="legend-dot" style={{ background: '#4ade80' }} /> Low</span>
              <span className="legend-item"><span className="legend-dot" style={{ background: '#60a5fa' }} /> Resource</span>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}

export default App;

