    webkitSpeechRecognition: new (options?: SpeechRecognitionOptions) => SpeechRecognition;
  }
}

interface UseSpeechRecognitionReturn {
  transcript: string;
  interimTranscript: string;
  isListening: boolean;
  startListening: () => void;
  stopListening: () => void;
  hasRecognitionSupport: boolean;
}

export function useSpeechRecognition(options: SpeechRecognitionOptions = {}): UseSpeechRecognitionReturn {
  const [transcript, setTranscript] = useState('');
  const [interimTranscript, setInterimTranscript] = useState('');
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<SpeechRecognition | null>(null);

  const hasRecognitionSupport = typeof window !== 'undefined' &&
    ('SpeechRecognition' in window || 'webkitSpeechRecognition' in window);

  useEffect(() => {
    if (!hasRecognitionSupport) return;

    const SpeechRecognitionClass = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognitionClass({
      lang: options.lang || 'en-US',
      continuous: options.continuous ?? false,
      interimResults: options.interimResults ?? true,
    });

    recognition.onresult = (event: SpeechRecognitionEvent) => {
      let final = '';
      let interim = '';
      for (let i = event.resultIndex; i < event.results.length; i += 1) {
        const result = event.results[i];
        if (result.isFinal) {
          final += result[0].transcript;
        } else {
          interim += result[0].transcript;
        }
      }
      if (final) {
        setTranscript((prev) => prev + final);
      }
      setInterimTranscript(interim);
    };

    recognition.onerror = () => {
      setIsListening(false);
      setInterimTranscript('');
    };

    recognition.onend = () => {
      setIsListening(false);
      setInterimTranscript('');
    };

    recognitionRef.current = recognition;

    return () => {
      recognition.abort();
    };
  }, [hasRecognitionSupport, options.lang, options.continuous, options.interimResults]);

  const startListening = useCallback(() => {
    if (!recognitionRef.current || isListening) return;
    setTranscript('');
    setInterimTranscript('');
    try {
      recognitionRef.current.start();
      setIsListening(true);
    } catch {
      // already started
    }
  }, [isListening]);

  const stopListening = useCallback(() => {
    if (!recognitionRef.current || !isListening) return;
    recognitionRef.current.stop();
    setIsListening(false);
  }, [isListening]);

  return {
    transcript,
    interimTranscript,
    isListening,
    startListening,
    stopListening,
    hasRecognitionSupport,
  };
}

type SpeakOptions = {
  text: string;
  lang?: string;
  rate?: number;
  pitch?: number;
  volume?: number;
  voice?: SpeechSynthesisVoice | null;
};

export function useSpeechSynthesis() {
  const speak = useCallback((options: SpeakOptions) => {
    if (typeof window === 'undefined' || !window.speechSynthesis) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(options.text);
    utterance.lang = options.lang || 'en-US';
    utterance.rate = options.rate ?? 1;
    utterance.pitch = options.pitch ?? 1;
    utterance.volume = options.volume ?? 1;
    if (options.voice) {
      utterance.voice = options.voice;
    }
    window.speechSynthesis.speak(utterance);
  }, []);

  const cancel = useCallback(() => {
    if (typeof window === 'undefined' || !window.speechSynthesis) return;
    window.speechSynthesis.cancel();
  }, []);

  return { speak, cancel };
}

import { useState, useCallback, useRef, useEffect } from 'react';
import { Mic, MicOff, Send, MapPin, X, Volume2, VolumeX } from 'lucide-react';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';
import { useSpeechSynthesis } from '../hooks/useSpeechSynthesis';
import './VoiceAssistant.css';

export interface Message {
  role: 'user' | 'assistant';
  text: string;
  focus?: { lat: number; lng: number } | null;
  areaId?: string | null;
}

interface VoiceAssistantProps {
  onMapFocus?: (lat: number, lng: number, areaId?: string | null) => void;
}

const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:8000';

export default function VoiceAssistant({ onMapFocus }: VoiceAssistantProps) {
  const [messages, setMessages] = useState<Message[]>([
    {
      role: 'assistant',
      text: 'PRISM voice assistant online. Ask me about incidents, areas, resources, or information voids.',
      focus: null,
      areaId: null,
    },
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [ttsEnabled, setTtsEnabled] = useState(true);
  const { speak, cancel: cancelTts } = useSpeechSynthesis();
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const hasSpokenWelcome = useRef(false);

  const {
    transcript,
    interimTranscript,
    isListening,
    startListening,
    stopListening,
    hasRecognitionSupport,
  } = useSpeechRecognition({ continuous: false, interimResults: true });

  useEffect(() => {
    if (!hasSpokenWelcome.current) {
      hasSpokenWelcome.current = true;
      if (ttsEnabled) {
        speak({
          text: 'PRISM voice assistant online. Ask me about incidents, areas, resources, or information voids.',
          rate: 1.1,
        });
      }
    }
  }, [speak, ttsEnabled]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendQuery = useCallback(
    async (text: string) => {
      if (!text.trim() || isLoading) return;
      const userMessage: Message = { role: 'user', text: text.trim(), focus: null, areaId: null };
      setMessages((prev) => [...prev, userMessage]);
      setInput('');
      setIsLoading(true);
      try {
        const res = await fetch(`${API_BASE}/api/intelligence/query`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ query: text }),
        });
        if (!res.ok) throw new Error('Query failed');
        const data = await res.json();
        const responseText = data.response?.answer || 'No response.';
        const focusLat = data.response?.focus_lat ?? null;
        const focusLng = data.response?.focus_lng ?? null;
        const areaId = data.response?.area_id ?? null;
        const assistantMessage: Message = {
          role: 'assistant',
          text: responseText,
          focus: focusLat != null && focusLng != null ? { lat: focusLat, lng: focusLng } : null,
          areaId,
        };
        setMessages((prev) => [...prev, assistantMessage]);
        if (ttsEnabled) {
          speak({ text: responseText, rate: 1.1 });
        }
        if (focusLat != null && focusLng != null && onMapFocus) {
          onMapFocus(focusLat, focusLng, areaId);
        }
      } catch {
        const errorMessage: Message = {
          role: 'assistant',
          text: 'I encountered an error. Please try again.',
          focus: null,
          areaId: null,
        };
        setMessages((prev) => [...prev, errorMessage]);
      } finally {
        setIsLoading(false);
      }
    },
    [isLoading, onMapFocus, speak, ttsEnabled]
  );

  const handleMicClick = useCallback(() => {
    if (isListening) {
      stopListening();
      if (transcript) {
        sendQuery(transcript);
      }
    } else {
      cancelTts();
      startListening();
    }
  }, [isListening, stopListening, transcript, sendQuery, startListening, cancelTts]);

  const handleSubmit = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault();
      sendQuery(input);
    },
    [input, sendQuery]
  );

  useEffect(() => {
    if (!isListening && transcript) {
      sendQuery(transcript);
    }
  }, [isListening, transcript, sendQuery]);

  return (
    <div className="voice-assistant">
      <div className="voice-assistant__header">
        <div className="voice-assistant__title">
          <Volume2 size={16} />
          <span>PRISM Assistant</span>
        </div>
        <div className="voice-assistant__controls">
          <button
            type="button"
            className="voice-assistant__icon-btn"
            onClick={() => {
              setTtsEnabled((prev) => {
                const next = !prev;
                if (!next) cancelTts();
                return next;
              });
            }}
            title={ttsEnabled ? 'Mute voice' : 'Unmute voice'}
          >
            {ttsEnabled ? <Volume2 size={14} /> : <VolumeX size={14} />}
          </button>
          <button
            type="button"
            className="voice-assistant__icon-btn"
            onClick={() => setMessages([])}
            title="Clear chat"
          >
            <X size={14} />
          </button>
        </div>
      </div>

      <div className="voice-assistant__messages">
        {messages.map((message, index) => (
          <div key={index} className={`voice-assistant__message voice-assistant__message--${message.role}`}>
            <div className="voice-assistant__bubble">
              <p>{message.text}</p>
              {message.focus && (
                <button
                  type="button"
                  className="voice-assistant__focus"
                  onClick={() => onMapFocus?.(message.focus!.lat, message.focus!.lng, message.areaId)}
                >
                  <MapPin size={12} />
                  <span>Focus map</span>
                </button>
              )}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="voice-assistant__message voice-assistant__message--assistant">
            <div className="voice-assistant__bubble voice-assistant__typing">
              <span />
              <span />
              <span />
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form className="voice-assistant__footer" onSubmit={handleSubmit}>
        <input
          type="text"
          className="voice-assistant__input"
          placeholder="Ask PRISM..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
          disabled={isLoading}
        />
        <button
          type="button"
          className={`voice-assistant__mic ${isListening ? 'voice-assistant__mic--active' : ''}`}
          onClick={handleMicClick}
          disabled={!hasRecognitionSupport}
          title={hasRecognitionSupport ? (isListening ? 'Stop listening' : 'Start listening') : 'Speech recognition not supported'}
        >
          {isListening ? <MicOff size={18} /> : <Mic size={18} />}
        </button>
        <button type="submit" className="voice-assistant__send" disabled={!input.trim() || isLoading}>
          <Send size={18} />
        </button>
      </form>

      {isListening && (
        <div className="voice-assistant__interim">
          {interimTranscript || 'Listening...'}
        </div>
      )}
    </div>
  );
}

.voice-assistant {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: #0b0f14;
  border: 1px solid #1f2937;
  border-radius: 6px;
  overflow: hidden;
  color: #e5e7eb;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.voice-assistant__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  border-bottom: 1px solid #1f2937;
  background: #0f1419;
}

.voice-assistant__title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #9ca3af;
}

.voice-assistant__controls {
  display: flex;
  align-items: center;
  gap: 6px;
}

.voice-assistant__icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  border-radius: 4px;
  border: 1px solid #1f2937;
  background: #0b0f14;
  color: #9ca3af;
  cursor: pointer;
}

.voice-assistant__icon-btn:hover {
  color: #e5e7eb;
  border-color: #374151;
}

.voice-assistant__messages {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.voice-assistant__message {
  display: flex;
}

.voice-assistant__message--user {
  justify-content: flex-end;
}

.voice-assistant__message--assistant {
  justify-content: flex-start;
}

.voice-assistant__bubble {
  max-width: 85%;
  padding: 10px 12px;
  border-radius: 6px;
  border: 1px solid #1f2937;
  background: #111827;
  line-height: 1.45;
  font-size: 14px;
}

.voice-assistant__message--user .voice-assistant__bubble {
  background: #0a1f1a;
  border-color: #14532d;
  color: #bbf7d0;
}

.voice-assistant__message--assistant .voice-assistant__bubble {
  color: #e5e7eb;
}

.voice-assistant__bubble p {
  margin: 0;
}

.voice-assistant__focus {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
  padding: 6px 8px;
  border-radius: 4px;
  border: 1px solid #14532d;
  background: #052e16;
  color: #86efac;
  font-size: 12px;
  cursor: pointer;
}

.voice-assistant__focus:hover {
  background: #064e2e;
}

.voice-assistant__typing {
  display: flex;
  gap: 6px;
  padding: 12px;
}

.voice-assistant__typing span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #6b7280;
  animation: voice-assistant__pulse 1.2s infinite ease-in-out;
}

.voice-assistant__typing span:nth-child(1) {
  animation-delay: 0s;
}
.voice-assistant__typing span:nth-child(2) {
  animation-delay: 0.2s;
}
.voice-assistant__typing span:nth-child(3) {
  animation-delay: 0.4s;
}

@keyframes voice-assistant__pulse {
  0%,
  80%,
  100% {
    transform: scale(0.6);
    opacity: 0.4;
  }
  40% {
    transform: scale(1);
    opacity: 1;
  }
}

.voice-assistant__footer {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-top: 1px solid #1f2937;
  background: #0f1419;
}

.voice-assistant__input {
  flex: 1;
  padding: 8px 10px;
  border-radius: 4px;
  border: 1px solid #1f2937;
  background: #0b0f14;
  color: #e5e7eb;
  font-size: 14px;
  outline: none;
}

.voice-assistant__input:focus {
  border-color: #14532d;
}

.voice-assistant__mic,
.voice-assistant__send {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
  border-radius: 4px;
  border: 1px solid #1f2937;
  background: #0b0f14;
  color: #9ca3af;
  cursor: pointer;
}

.voice-assistant__mic:hover,
.voice-assistant__send:hover {
  color: #e5e7eb;
  border-color: #374151;
}

.voice-assistant__mic--active {
  color: #ef4444;
  border-color: #7f1d1d;
  background: #1a0f0f;
  animation: voice-assistant__mic-pulse 1.5s infinite;
}

@keyframes voice-assistant__mic-pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.35);
  }
  50% {
    box-shadow: 0 0 0 8px rgba(239, 68, 68, 0);
  }
}

.voice-assistant__interim {
  padding: 0 12px 10px;
  font-size: 12px;
  color: #6b7280;
  font-style: italic;
  min-height: 18px;
}

.app {
  display: flex;
  flex-direction: column;
  height: 100vh;
  background: #07090c;
  color: #e5e7eb;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.app__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-bottom: 1px solid #1f2937;
  background: #0b0f14;
}

.app__brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #9ca3af;
}

.app__status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #ef4444;
  letter-spacing: 0.1em;
}

.app__main {
  display: grid;
  grid-template-columns: 1fr 380px;
  flex: 1;
  min-height: 0;
}

.app__map {
  border-right: 1px solid #1f2937;
  background: #0a0d12;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.map-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  color: #6b7280;
  text-align: center;
}

.map-placeholder__hint {
  font-size: 12px;
  color: #4b5563;
}

.map-focus {
  margin-top: 10px;
  padding: 10px 12px;
  border: 1px solid #14532d;
  background: #052e16;
  color: #bbf7d0;
  border-radius: 6px;
  font-size: 13px;
  line-height: 1.5;
}

.map-focus strong {
  color: #86efac;
}

.app__sidebar {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  margin: 0;
  padding: 0;
  height: 100%;
  background: #07090c;
  color: #e5e7eb;
}

