try {
  $r = Invoke-RestMethod -Uri 'http://localhost:8000/api/intelligence/query' -Method Post -ContentType 'application/json' -Body '{"query":"What is the status of Bhangagarh?"}'
  $r | ConvertTo-Json -Depth 5
