 77	  // ---- Activity always ongoing ----
 78	  useEffect(() => {
 79	    if (selectedWardCode && wardActivity[selectedWardCode]) {
 80	      setActivity(wardActivity[selectedWardCode].slice());
 81	    } else if (selectedWardCode) {
 82	      const seed = selectedWardCode % 40;
 83	      const base = 14 + seed % 10;
