 93	        const next = prev.slice(1);
 94	        const last = prev[prev.length - 1];
 95	        if (selectedWardCode === 69102) next.push(0.9 + Math.random() * 0.6);
 96	        else if (selectedWardCode) {
 97	          const delta = (Math.random() - 0.5) * 2.2;
