321	        const next = stepSimulatedResources(prev, tick);
322	        setResourceTrails(mprev => {
323	          const nm = new Map(mprev);
324	          for (const r of next) {
325	            const cur = nm.get(r.id) ?? [];
326	            const last = cur[cur.length - 1];
327	            if (!last || last[0] !== r.lng || last[1] !== r.lat) {
328	              nm.set(r.id, [...cur, [r.lng, r.lat] as [number, number]].slice(-42));
329	            }
330	          }
331	          return nm;
332	        });
333	        return next;
334	      });
335	    }, 120);
336	    return () => clearInterval(id);
337	  }, [planPhase]);
338	
339	  // ---- WebSocket live updates ----
340	  useEffect(() => {
341	    if (simulationState !== "running") return;
342	
343	    const url = wsUrl();
344	    const ws = new WebSocket(url);
345	
346	    ws.onopen = () => {
347	      // connection established — live feed active
348	    };
349	
350	    ws.onmessage = (event) => {
351	      try {
352	        const msg = JSON.parse(event.data);
353	        const eventType = msg.event;
354	        const payload = msg.payload;
355	
356	        if (eventType === "REPORT_RECEIVED") {
357	          setReports(prev => {
358	            const report: Report = {
359	              id: `RPT-WS-${Date.now()}`,
360	              incidentId: "",
361	              wardCode: 0,
362	              text: `${payload.source ?? "unknown"} @ ${payload.location ?? "unknown"}`,
363	              time: new Date().toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", hour12: false }),
364	              source: "field",
365	              verified: false,
366	            };
367	            return [report, ...prev].slice(0, 32);
368	          });
369	        } else if (eventType === "INCIDENT_UPDATED") {
370	          setIncidents(prev =>
371	            prev.map(inc =>
372	              inc.id === payload.incident_id
373	                ? { ...inc, status: payload.status === "active" ? "reported" : payload.status === "monitoring" ? "verified" : payload.status === "contained" ? "dispatched" : payload.status === "resolved" ? "resolved" : inc.status }
374	                : inc
375	            )
376	          );
377	        } else if (eventType === "RESOURCE_ASSIGNED") {
378	          setMovingAssets(prev => [
379	            ...prev,
380	            {
381	              id: `MOV-WS-${payload.resource_id}`,
382	              lon: 91.73,
383	              lat: 26.14,
384	              label: `${payload.resource_id} → ${payload.incident_id}`,
385	              kind: "ambulance",
386	              progress: 0,
387	              trail: [[91.73, 26.14]],
388	              etaMin: payload.eta_minutes ?? 10,
389	              totalMin: payload.eta_minutes ?? 10,
390	            },
391	          ]);
392	        } else if (eventType === "INFORMATION_VOID_DETECTED") {
393	          // void state can be updated here if needed
394	        } else if (eventType === "SIMULATION_TICK") {
395	          // tick counter or phase updates can be handled here
396	        }
397	      } catch {
398	        // ignore malformed WS messages
399	      }
400	    };
401	
402	    ws.onclose = () => {
403	      // WebSocket closed — local simulation continues as fallback
404	    };
405	
406	    ws.onerror = () => {
407	      ws.close();
408	    };
409	
410	    return () => {
411	      ws.close();
412	    };
413	  }, [simulationState]);
414	
415	  useEffect(() => {
416	    if (simulationState === "idle") {
417	      reportIdx.current = 0;
418	      sourceIdx.current = 0;
419	      simCounter.current = 0;
420	      setReports([]);
421	      setSources([]);
422	      setIncidents([]);
423	      setResources([]);
424	      setPlan([]);
425	      setPlanPhase("idle");
426	      setMovingAssets([]);
427	      // hide fleet until next dispatch — user request: no boats visible before plan
428	      setPrismResources([]);
429	      setResourceTrails(new Map());
430	      setSelectedResourceId(null);
431	      setSelectedWardCode(null);
432	      setSelectedIncidentId(null);
433	    }
434	  }, [simulationState]);
435	
436	  const planReady = planPhase === "ready";
437	  const selectedResource = selectedResourceId ? prismResources.find(r => r.id === selectedResourceId) ?? null : null;
438	
439	  const value = useMemo<PrismContextValue>(() => ({
440	    selectedWardCode,
441	    selectedIncidentId,
442	    mapMode,
443	    simulationState,
444	    selectWard: setSelectedWardCode,
445	    selectIncident: setSelectedIncidentId,
446	    setMapMode,
447	    setSimulationState,
448	    selectedWardName: selectedWardCode ? incidents.find(i => i.wardCode === selectedWardCode)?.wardName ?? `Ward ${selectedWardCode}` : null,
449	    incidents,
450	    resources,
451	    prismResources,
452	    selectedResourceId,
453	    selectResource: setSelectedResourceId,
454	    resourceTrails,
455	    selectedResource,
456	    reports,
457	    sources,
458	    activity,
459	    plan,
460	    planReady,
461	    planPhase,
462	    movingAssets,
463	    api: {
464	      reportsEndpoint: "GET /api/reports",
465	      incidentsEndpoint: "GET /api/incidents",
466	      resourcesEndpoint: "GET /api/resources",
467	      wsEndpoint: "WS /api/simulation/ws/live",
468	    },
469	  }), [selectedWardCode, selectedIncidentId, mapMode, simulationState, reports, sources, activity, plan, planReady, planPhase, incidents, movingAssets, prismResources, selectedResourceId, resourceTrails, selectedResource, resources]);
470	
471	  return <PrismContext.Provider value={value}>{children}</PrismContext.Provider>;
472	}
473	
474	export function usePrism() {
475	  const ctx = useContext(PrismContext);
476	  if (!ctx) throw new Error("usePrism must be inside PrismProvider");
477	  return ctx;
478	}

