 93	.prism-map { grid-area: map; position: relative; overflow: hidden; background: #020305; }
 94	.prism-right { grid-area: right; }
 95	.prism-bottom { grid-area: bottom; }
 96	
 97	/* HUD Panel */
 98	.panel {
 99	  background: linear-gradient(180deg, rgba(17,25,30,0.96), rgba(10,13,15,0.98));
100	  border: 1px solid var(--border);
101	  display: flex;
102	  flex-direction: column;
103	  overflow: hidden;
104	  position: relative;
105	}
106	
107	/* corner brackets */
108	.panel::before, .panel::after,
109	.prism-map::before, .prism-map::after {
110	  content: "";
111	  position: absolute;
112	  width: 14px; height: 14px;
113	  pointer-events: none;
114	  z-index: 3;
115	}
116	.panel::before { top: -1px; left: -1px; border-top: 1.5px solid rgba(204,255,0,0.65); border-left: 1.5px solid rgba(204,255,0,0.65); }
117	.panel::after { top: -1px; right: -1px; border-top: 1.5px solid rgba(204,255,0,0.35); border-right: 1.5px solid rgba(204,255,0,0.35); }
118	.prism-map::before { top: -1px; left: -1px; border-top: 1.5px solid rgba(204,255,0,0.9); border-left: 1.5px solid rgba(204,255,0,0.9); }
119	.prism-map::after { bottom: -1px; right: -1px; border-bottom: 1.5px solid rgba(204,255,0,0.35); border-right: 1.5px solid rgba(204,255,0,0.35); }
120	
121	.panel-header {
122	  height: 34px; min-height: 34px;
123	  display: flex; align-items: center; justify-content: space-between;
124	  padding: 0 10px 0 12px;
125	  border-bottom: 1px solid var(--border);
126	  background: linear-gradient(90deg, rgba(204,255,0,0.06), transparent 55%), var(--bg-panel-2);
127	  position: relative;
128	}
129	.panel-header::after {
130	  content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 1px;
131	  background: linear-gradient(90deg, rgba(204,255,0,0.35), transparent 60%);
132	  opacity: 0.6;
133	}
134	.panel-title {
135	  font-family: var(--font-mono);
136	  font-size: 9.5px; letter-spacing: 0.15em; font-weight: 700;
137	  color: var(--text-dim); text-transform: uppercase;
138	  display: flex; align-items: center; gap: 8px;
139	}
140	.panel-title-dot {
141	  width: 6px; height: 6px; border-radius: 50%;
142	  background: var(--lime); box-shadow: 0 0 10px rgba(204,255,0,0.85);
143	  animation: pulse 1.8s infinite;
144	}
