@@ -0,0 +1,218 @@
+import { useEffect, useState } from "react";
+import { motion, AnimatePresence } from "framer-motion";
+import { CloudRain, Wind, Thermometer, AlertTriangle, MapPin, Loader2 } from "lucide-react";
+import { usePrism } from "../store/PrismContext";
+import { fetchPrediction, type WeatherPrediction } from "../services/api";
+
+const GUWAHATI_CENTER = { lat: 26.1445, lon: 91.7362 };
+
+const DISASTER_LABELS: Record<string, string> = {
+  flood: "Flood",
+  cyclone: "Cyclone",
+  heatwave: "Heatwave",
+  cold_wave: "Cold Wave",
+  fire: "Fire",
+  landslide: "Landslide",
+  earthquake: "Earthquake",
+  storm: "Storm",
+  none: "No Threat",
+};
+
+const SEVERITY_COLORS: Record<string, string> = {
+  low: "var(--green)",
+  moderate: "var(--amber)",
+  high: "var(--red)",
+  critical: "#ff3838",
+};
+
+function severityColor(s: string): string {
+  return SEVERITY_COLORS[s] ?? "var(--text-muted)";
+}
+
+export function WeatherPanel() {
+  const { selectedWardCode, incidents, weatherByLocation, simulationState } = usePrism();
+  const [prediction, setPrediction] = useState<WeatherPrediction | null>(null);
+  const [loading, setLoading] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const [source, setSource] = useState<"idle" | "rest" | "ws">("idle");
+
+  const incidentForWard = selectedWardCode
+    ? incidents.find(i => i.wardCode === selectedWardCode)
+    : null;
+  const lat = incidentForWard?.lat ?? GUWAHATI_CENTER.lat;
+  const lon = incidentForWard?.lon ?? GUWAHATI_CENTER.lon;
+  const locationName = incidentForWard
+    ? `${incidentForWard.wardName} (Ward ${selectedWardCode})`
+    : "Guwahati, Assam";
+
+  useEffect(() => {
+    let cancelled = false;
+    setLoading(true);
+    setError(null);
+    fetchPrediction(lat, lon)
+      .then(data => {
+        if (!cancelled) {
+          setPrediction(data);
+          setSource("rest");
+          setLoading(false);
+        }
+      })
+      .catch(err => {
+        if (!cancelled) {
+          setError(err instanceof Error ? err.message : "Forecast unavailable");
+          setLoading(false);
+        }
+      });
+    return () => {
+      cancelled = true;
+    };
+  }, [lat, lon]);
+
+  useEffect(() => {
+    if (simulationState !== "running") return;
+    const centerKey = Object.keys(weatherByLocation).find(k => k === "GUWAHATI-CENTER");
+    const match = centerKey ? weatherByLocation[centerKey] : null;
+    if (match) {
+      setPrediction(match);
+      setSource("ws");
+      setError(null);
+    }
+  }, [weatherByLocation, simulationState]);
+
+  const primary = prediction?.prediction;
+  const weather = prediction?.weather;
+
+  return (
+    <div style={{ padding: 10, background: "var(--bg-panel)", borderTop: "1px solid var(--border)" }}>
+      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 6 }}>
+        <span className="panel-title" style={{ fontSize: 10, color: "var(--cyan)" }}>
+          <CloudRain size={11} /> FORECAST RISK
+        </span>
+        <span className="mono" style={{ fontSize: 8, color: "var(--text-faint)" }}>
+          <MapPin size={9} style={{ verticalAlign: "middle" }} /> {locationName}
+        </span>
+      </div>
+
+      <AnimatePresence mode="wait">
+        {loading ? (
+          <motion.div
+            key="loading"
+            initial={{ opacity: 0 }}
+            animate={{ opacity: 1 }}
+            exit={{ opacity: 0 }}
+            style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 0" }}
+          >
+            <Loader2 size={11} className="animate-spin" style={{ color: "var(--text-muted)" }} />
+            <span className="mono" style={{ fontSize: 9, color: "var(--text-muted)" }}>
+              Querying wttr.in + AI analysis...
+            </span>
+          </motion.div>
+        ) : error ? (
+          <motion.div
+            key="error"
+            initial={{ opacity: 0 }}
+            animate={{ opacity: 1 }}
+            exit={{ opacity: 0 }}
+            className="mono"
+            style={{ fontSize: 9, color: "var(--text-muted)", padding: "6px 0" }}
+          >
+            {error}. Using fallback heuristics.
+          </motion.div>
+        ) : primary && weather ? (
+          <motion.div
+            key="data"
+            initial={{ opacity: 0, y: 6 }}
+            animate={{ opacity: 1, y: 0 }}
+            exit={{ opacity: 0 }}
+            transition={{ duration: 0.35 }}
+            style={{ display: "flex", flexDirection: "column", gap: 6 }}
+          >
+            <div
+              style={{
+                background: primary.disaster_type === "none" ? "rgba(70,224,155,0.08)" : "rgba(255,77,77,0.08)",
+                border: `1px solid ${primary.disaster_type === "none" ? "rgba(70,224,155,0.3)" : "rgba(255,77,77,0.3)"}`,
+                borderRadius: 3,
+                padding: 8,
+              }}
+            >
+              <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 4 }}>
+                {primary.disaster_type !== "none" && (
+                  <AlertTriangle size={12} style={{ color: severityColor(primary.severity) }} />
+                )}
+                <span
+                  className="mono"
+                  style={{
+                    fontSize: 11,
+                    fontWeight: 800,
+                    letterSpacing: "0.08em",
+                    color: severityColor(primary.severity),
+                  }}
+                >
+                  {DISASTER_LABELS[primary.disaster_type] ?? primary.disaster_type.toUpperCase()} SUSPECTED
+                </span>
+                <span
+                  className="mono"
+                  style={{
+                    fontSize: 8,
+                    marginLeft: "auto",
+                    padding: "1px 5px",
+                    borderRadius: 2,
+                    background: severityColor(primary.severity),
+                    color: "#000",
+                    fontWeight: 700,
+                  }}
+                >
+                  {primary.severity.toUpperCase()}
+                </span>
+              </div>
+              <div style={{ fontSize: 10, color: "var(--text-dim)", lineHeight: 1.4, marginBottom: 4 }}>
+                {primary.reason}
+              </div>
+              <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
+                <span className="mono" style={{ fontSize: 8, color: "var(--text-faint)" }}>AI CONFIDENCE</span>
+                <div style={{ flex: 1, height: 4, background: "#0e191d", borderRadius: 999, overflow: "hidden", border: "1px solid var(--border)" }}>
+                  <motion.div
+                    initial={{ width: 0 }}
+                    animate={{ width: `${primary.confidence}%` }}
+                    transition={{ duration: 0.7, ease: "easeOut" }}
+                    style={{ height: "100%", background: severityColor(primary.severity) }}
+                  />
+                </div>
+                <span className="mono" style={{ fontSize: 9, fontWeight: 700, color: severityColor(primary.severity) }}>
+                  {primary.confidence}%
+                </span>
+              </div>
+            </div>
+
+            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 4 }}>
+              <div className="mono" style={{ fontSize: 9, color: "var(--text-muted)", display: "flex", alignItems: "center", gap: 3 }}>
+                <CloudRain size={9} style={{ color: "var(--cyan)" }} />
+                <span>{weather.rainfall_next_6h_mm}mm / 6h</span>
+              </div>
+              <div className="mono" style={{ fontSize: 9, color: "var(--text-muted)", display: "flex", alignItems: "center", gap: 3 }}>
+                <Thermometer size={9} style={{ color: "var(--amber)" }} />
+                <span>{weather.rain_probability}% rain</span>
+              </div>
+              <div className="mono" style={{ fontSize: 9, color: "var(--text-muted)", display: "flex", alignItems: "center", gap: 3 }}>
+                <Wind size={9} style={{ color: "var(--green)" }} />
+                <span>Risk {weather.forecast_risk}</span>
+              </div>
+            </div>
+
+            {weather.suspected_disasters.length > 1 && (
+              <div className="mono" style={{ fontSize: 8, color: "var(--text-faint)", lineHeight: 1.4 }}>
+                Also flagged: {weather.suspected_disasters.slice(1).map(d => DISASTER_LABELS[d] ?? d).join(", ")}
+              </div>
+            )}
+          </motion.div>
+        ) : null}
+      </AnimatePresence>
+
+      <div className="mono" style={{ fontSize: 8, color: "var(--text-faint)", textAlign: "center", marginTop: 6 }}>
+        Source: <span style={{ color: "var(--text-muted)" }}>wttr.in</span> + AI • Generic disaster model (flood / cyclone / heatwave / cold / fire / landslide / quake)
+        {source === "ws" && <span style={{ color: "var(--lime)", marginLeft: 6 }}>● LIVE WS</span>}
+        {source === "rest" && <span style={{ color: "var(--cyan)", marginLeft: 6 }}>● REST</span>}
+      </div>
+    </div>
+  );
+}
diff --git a/frontend/src/services/api.ts b/frontend/src/services/api.ts
new file mode 100644
index 0000000..a18f6c5
--- /dev/null
+++ b/frontend/src/services/api.ts
@@ -0,0 +1,227 @@
+import type { Incident, Report, Resource, WardProperties } from "../types/prism";
+import type { PrismResource } from "../resources/resourceTypes";
+import { toPrismResource } from "../resources/resourceTypes";
+
+// Backend raw shapes (FastAPI Pydantic schemas)
+export type BackendIncident = {
+  id: string;
+  title: string;
+  event_type: string;
+  latitude: number;
+  longitude: number;
+  area_id: string | null;
+  severity: string;
+  people_affected: number;
+  people_trapped: number;
+  vulnerable_population: number;
+  confidence: number;
+  priority: number;
+  status: string;
+  created_at: string;
+  updated_at: string;
+};
+
+export type BackendReport = {
+  id: string;
+  timestamp: string;
+  source_type: string;
+  source_name: string;
+  latitude: number;
+  longitude: number;
+  location_name: string;
+  raw_text: string;
+  media_type: string;
+  claimed_severity: number;
+  people_affected: number;
+  people_trapped: number;
+  vulnerable_population: number;
+  event_type: string;
+  evidence_type: string;
+  confidence: number;
+  status: string;
+  incident_id: string | null;
+  created_at: string;
+};
+
+export type BackendResource = {
+  id: string;
+  type: string;
+  status: string;
+  latitude: number;
+  longitude: number;
+  capacity: number;
+  availability: number;
+  created_at: string;
+  updated_at: string;
+};
+
+export type BackendArea = {
+  id: string;
+  name: string;
+  latitude: number;
+  longitude: number;
+  population: number;
+  vulnerable_population: number;
+  status: string;
+  risk_score: number;
+  priority: number;
+  confidence: number;
+  information_void_score: number;
+  last_verified: string | null;
+  report_count: number;
+  created_at: string;
+  updated_at: string;
+};
+
+function apiBase(): string {
+  return import.meta.env.VITE_API_URL ?? "";
+}
+
+export function wsUrl(): string {
+  const base = apiBase();
+  if (base) {
+    return base.replace(/^http/, "ws") + "/api/simulation/ws/live";
+  }
+  return `${window.location.protocol === "https:" ? "wss:" : "ws:"}//${window.location.host}/api/simulation/ws/live`;
+}
+
+function timeStr(iso: string): string {
+  return new Date(iso).toLocaleTimeString("en-IN", {
+    hour: "2-digit",
+    minute: "2-digit",
+    hour12: false,
+  });
+}
+
+function mapIncidentStatus(status: string): Incident["status"] {
+  switch (status) {
+    case "active":
+      return "reported";
+    case "monitoring":
+      return "verified";
+    case "contained":
+      return "dispatched";
+    case "resolved":
+      return "resolved";
+    default:
+      return "reported";
+  }
+}
+
+function mapResourceType(type: string): Resource["type"] {
+  const t = type.toLowerCase();
+  if (["medical", "rescue", "shelter", "food", "transport"].includes(t)) {
+    return t as Resource["type"];
+  }
+  return "medical";
+}
+
+function mapResourceStatus(status: string): Resource["status"] {
+  const s = status.toLowerCase();
+  if (["available", "deployed", "standby"].includes(s)) {
+    return s as Resource["status"];
+  }
+  return "available";
+}
+
+export function toIncident(r: BackendIncident): Incident {
+  const raw = r.area_id ? parseInt(r.area_id, 10) : 0;
+  const wardCode = isNaN(raw) ? 0 : raw;
+  return {
+    id: r.id,
+    wardCode,
+    wardName: r.area_id ? `Area ${r.area_id}` : "Unknown",
+    title: r.title,
+    severity: r.severity as Incident["severity"],
+    status: mapIncidentStatus(r.status),
+    confidence: r.confidence,
+    priority: r.priority,
+    lat: r.latitude,
+    lon: r.longitude,
+    time: `${timeStr(r.created_at)} IST`,
+    reports: 0,
+    summary: r.event_type,
+  };
+}
+
+export function toReport(r: BackendReport): Report {
+  return {
+    id: r.id,
+    incidentId: r.incident_id ?? "UNKNOWN",
+    wardCode: 0,
+    text: r.raw_text,
+    time: timeStr(r.timestamp),
+    source: r.source_type as Report["source"],
+    verified: r.status === "verified",
+  };
+}
+
+export function toResource(r: BackendResource): Resource {
+  return {
+    id: r.id,
+    type: mapResourceType(r.type),
+    status: mapResourceStatus(r.status),
+    wardCode: 0,
+    lat: r.latitude,
+    lon: r.longitude,
+    capacity: r.capacity,
+  };
+}
+
+export function toWard(r: BackendArea): WardProperties {
+  const raw = parseInt(r.id, 10);
+  const objectid = isNaN(raw) ? 0 : raw;
+  return {
+    objectid,
+    ward_lgd_code: objectid,
+    ward_lgd_name: r.name,
+    sourcewardcode: r.id,
+    townname: "Guwahati",
+    state: "Assam",
+  };
+}
+
+export async function fetchIncidents(signal?: AbortSignal): Promise<Incident[]> {
