+  event_type: string;
+  latitude: number;
+  longitude: number;
+  area_id: string | null;
+  severity: string;
+  people_affected: number;
+  people_trapped: number;
+  vulnerable_population: number;
+  confidence: number;
+  priority: number;
+  status: string;
+  created_at: string;
+  updated_at: string;
+};
+
+export type BackendReport = {
+  id: string;
+  timestamp: string;
+  source_type: string;
+  source_name: string;
+  latitude: number;
+  longitude: number;
+  location_name: string;
+  raw_text: string;
+  media_type: string;
+  claimed_severity: number;
+  people_affected: number;
+  people_trapped: number;
+  vulnerable_population: number;
+  event_type: string;
+  evidence_type: string;
+  confidence: number;
+  status: string;
+  incident_id: string | null;
+  created_at: string;
+};
+
+export type BackendResource = {
+  id: string;
+  type: string;
+  status: string;
+  latitude: number;
+  longitude: number;
