    const t = trails.get(r.id);
    if (!t || t.length < 2) continue;
    feats.push({
      type: "Feature",
      properties: { id: r.id, kind: r.kind },
      geometry: { type: "LineString", coordinates: t as unknown as number[][] },
    });
  }
  return { type: "FeatureCollection", features: feats };
}

