19	/** Lightweight descriptor for backend GET /api/resources → PrismResource adapter */
20	export function toPrismResource(raw: unknown): PrismResource | null {
21	  const r = raw as Record<string, unknown>;
22	  if (!r || typeof r.id !== "string") return null;
23	  const kind = String(r.kind ?? r.type ?? "ambulance") as ResourceKind;
24	  return {
25	    id: String(r.id),
26	    kind: ["ambulance", "helicopter", "boat", "rescue_vehicle"].includes(kind) ? kind : "ambulance",
