28	    lng: Number(r.lng ?? r.lon ?? r.longitude ?? 91.73),
29	    heading: Number(r.heading ?? 0),
30	    status: (String(r.status ?? "available") as ResourceStatus) || "available",
31	    speed: r.speed != null ? Number(r.speed) : undefined,
32	    destination: r.destination ? String(r.destination) : undefined,
33	    destLon: r.destLon != null ? Number(r.destLon) : r.dest_lng != null ? Number(r.dest_lng) : undefined,
